public class MixedDemo {
    public static void main(String[] args) {
        System.out.println(25 / 2 * 2.0);      // 24.0
        System.out.println(25.0 / 2.0 * 2);    // 25.0
        System.out.println(25.0 / 2 * 2);      // 25.0
        System.out.println(6 / 4 + 3.9);       // 4.9, 6/4 is 1, not 1.5
        System.out.println(11.5 + 3 * 2.25);   // 18.25
    }
}
